data=json.load(open(p))

def recursive_find_notifications(x):
    found=[]
    if isinstance(x,dict):
        if 'notifications' in x:
            found.append(x['notifications'])
        for v in x.values(): found += recursive_find_notifications(v)
    elif isinstance(x,list):
        for v in x: found += recursive_find_notifications(v)
    elif isinstance(x,str):
        try:
            found += recursive_find_notifications(json.loads(x))
        except: pass
    return found
for st in data['steps']:
    found=recursive_find_notifications(st.get('observation'))
    non=[n for n in found if n]
    if found:
        print('step',st['step_id'], 'tool', st.get('extra',{}).get('tool_use_name'), 'notifications containers', len(found),'nonempty', len(non))
